    private List<String> unpack(String downloadFilePath, String fileName, String encoding, String serviceName) {
        String filepath = downloadFilePath + File.separator + fileName;
        String folder = fileName.split("\\.")[0];
        String outPath = downloadFilePath + File.separator + folder;

        if (dynamicConfig.getUnpackType() == 0) {
            ZipUtil.decompression(filepath, outPath, encoding);
        } else if (dynamicConfig.getUnpackType() == 1) {
            ZipUtil.unZip(filepath, outPath, encoding);
        } else if (dynamicConfig.getUnpackType() == 2) {
            ZipUtil.unpack(filepath, outPath, encoding);
