            }
            fileHandleTaskTunnel.update(fileHandleTaskDo);
        } catch (IOException e) {
            throw new BusinessException(e);
        } catch (Exception e) {
            log.error("File handle task no:" + fileHandleTaskDo.getFileHandleTaskNo() + ",Exception occur:", e);
            fileHandleTaskDo.setHandleStatus(FileHandleStatus.FAIL.getCode());
            fileHandleTaskTunnel.update(fileHandleTaskDo);
        } finally {
            if (targetFile != null) {
                FileUtils.deleteQuietly(targetFile);
            }
        }
    }

